use lg_core::{AccountId, Date, Money, Txn};
use lg_store::{Query, Store};

fn txn(day: u8, cat: &str) -> Txn {
    Txn::new(Date::ymd(2024, 3, day), AccountId::parse("ativo:banco").unwrap(), "X", Money::of(-100, "BRL")).with_category(cat)
}

#[test]
fn disc_l10() {
    let mut s = Store::new();
    let a = s.insert(txn(1, "mercado"));
    s.insert(txn(2, "mercado"));
    let c = s.insert(txn(3, "lazer"));
    s.remove(a).unwrap();
    s.remove(c).unwrap();
    assert_eq!(Query::new().category("mercado").run(&s).len(), 1);
    assert!(Query::new().category("lazer").run(&s).is_empty());
    assert_eq!(s.categories(), vec!["mercado"]);
}
